package caddyfile

import (
	"bytes"
	"strings"
	"unicode/utf8"
)

// utf8BOM is the Unicode byte order mark that may prefix a UTF-8 file.
var utf8BOM = []byte{0xEF, 0xBB, 0xBF}

// formatSegment is a span of the input. Structural segments are fed
// through the whitespace/brace formatter; raw segments are copied to
// the result byte-for-byte (heredoc bodies, and the bytes of an
// unterminated heredoc opening line).
type formatSegment struct {
	raw    bool
	bytes  []byte // raw text, exactly as it appeared in the input (raw segments only)
	text   string // structural text, with CR line endings folded to LF (formatted segments only)
}

// Format formats the input Caddyfile to a standard, nice-looking
// appearance. It works by reading each rune of the input and taking
// control over all the bracing and whitespace that is written; otherwise,
// words, comments, placeholders, and escaped characters are all treated
// literally and written as they appear in the input.
//
// The bytes inside heredoc bodies, quoted arguments, and escaped
// characters are never reformatted. A single complete UTF-8 byte order
// mark at the very start of the input is preserved as a file marker.
//
// If the input cannot be formatted safely — an unclosed quote, a
// dangling escape, mismatched structural braces, an unterminated
// heredoc, or a truncated leading byte order mark — the input is
// returned byte-for-byte. The returned slice never aliases the input
// and carries no state from any other call.
func Format(input []byte) []byte {
	// A truncated byte order mark at the start of the input is not a
	// valid file marker; leave the bytes untouched.
	if n := truncatedBOMPrefixLen(input); n > 0 {
		return copyBytes(input)
	}

	hasBOM := bytes.HasPrefix(input, utf8BOM)
	body := input
	if hasBOM {
		body = input[len(utf8BOM):]
	}

	segs, ok := splitFormatSegments(body)
	if !ok {
		// malformed syntax (unterminated heredoc, quote, or escape):
		// return the input verbatim, including any leading BOM
		return copyBytes(input)
	}

	formatted, ok := formatSegments(segs)
	if !ok {
		// structural braces do not balance; return the input verbatim
		return copyBytes(input)
	}

	result := formatted
	if hasBOM {
		result = make([]byte, 0, len(utf8BOM)+len(formatted))
		result = append(result, utf8BOM...)
		result = append(result, formatted...)
	}

	// decouple the result from the input buffer and any internal
	// segment slices, which may alias it
	return copyBytes(result)
}

// truncatedBOMPrefixLen reports whether input starts with a proper,
// non-empty prefix of the UTF-8 BOM without being the whole BOM.
func truncatedBOMPrefixLen(input []byte) int {
	n := len(input)
	if n == 0 || n >= len(utf8BOM) || input[0] != utf8BOM[0] {
		return 0
	}
	for i := 0; i < n; i++ {
		if input[i] != utf8BOM[i] {
			return 0
		}
	}
	return n
}

// copyBytes returns a slice that does not alias b.
func copyBytes(b []byte) []byte {
	if len(b) == 0 {
		return nil
	}
	out := make([]byte, len(b))
	copy(out, b)
	return out
}

// splitFormatSegments divides the input into raw heredoc spans and
// structural spans. CR characters in structural spans are folded to LF
// (CRLF and bare CR alike); raw spans keep every original byte. It
// returns ok=false if the input contains an unterminated quote,
// dangling escape, or unterminated heredoc.
func splitFormatSegments(input []byte) ([]formatSegment, bool) {
	var segs []formatSegment

	var structural bytes.Buffer

	flushStructural := func() {
		if structural.Len() > 0 {
			segs = append(segs, formatSegment{text: structural.String()})
			structural.Reset()
		}
	}

	// appendRaw copies a span of input verbatim into a raw segment
	appendRaw := func(b []byte) {
		flushStructural()
		segs = append(segs, formatSegment{raw: true, bytes: copyBytes(b)})
	}

	// quote state, mirroring the lexer's accepted quote combinations:
	// "" (none), `"`, "`", "\"`", "`\""
	quotes := ""
	escaped := false

	// heredoc state
	var (
		inHeredoc       bool
		heredocMarker   []rune
		closingMatch    []rune // marker candidate on the current body line
		heredocOpenLine []byte // bytes from the opening "<<" up to (excluding) its newline
		bodyStart       int    // offset in input where the heredoc body begins
		pendingOpen     bool   // heredocOpenLine is waiting for its opening newline
	)

	for i := 0; i < len(input); {
		r, size := utf8.DecodeRune(input[i:])

		// A decoding error (RuneError from invalid UTF-8) in a
		// structural region is passed through as-is.
		ch := r

		if pendingOpen {
			// still accumulating the <<MARKER opening line
			switch ch {
			case '\r':
				// CR is skipped on the opening line just like the lexer does
				i += size
				continue
			case '\n':
				if len(heredocMarker) == 0 || !heredocMarkerRegexp.MatchString(string(heredocMarker)) {
					// not a heredoc after all; the buffered opening line
					// is ordinary structural text (its CRs were skipped,
					// matching the accepted grammar)
					pendingOpen = false
					structural.Write(heredocOpenLine)
					structural.WriteByte('\n')
					heredocOpenLine = nil
					heredocMarker = nil
					i += size
					continue
				}
				// a real heredoc starts here; emit the opening line as
				// structural text so its indentation can be normalized,
				// and the body (starting after this newline) is raw
				flushStructural()
				segs = append(segs, formatSegment{text: string(heredocOpenLine)})
				heredocOpenLine = nil
				bodyStart = i + size
				inHeredoc = true
				pendingOpen = false
				closingMatch = closingMatch[:0]
				i += size
				continue
			case ' ', '\t':
				// whitespace on the opening line means "<<" is an
				// ordinary token, unless a marker was already being
				// built and this whitespace is after it (the lexer
				// treats a space immediately after << as non-heredoc)
				if len(heredocMarker) == 0 {
					pendingOpen = false
					structural.Write(heredocOpenLine)
					heredocOpenLine = nil
					structural.WriteRune(ch)
					i += size
					continue
				}
				// trailing whitespace after the marker: fall through,
				// buffering it as part of the opening line
			}
			heredocOpenLine = appendRuneBytes(heredocOpenLine, input[i:i+size])
			if ch != ' ' && ch != '\t' {
				heredocMarker = append(heredocMarker, ch)
			}
			i += size
			continue
		}

		if inHeredoc {
			// body bytes are raw; only the closing marker, on its own
			// line boundary, ends the heredoc
			if ch == '\n' {
				closingMatch = closingMatch[:0]
				i += size
				continue
			}
			closingMatch = append(closingMatch, ch)
			if len(closingMatch) > len(heredocMarker)+1 {
				closingMatch = closingMatch[1:]
			}
			if isSpace(ch) && bytes.EqualRunes(closingMatch[:len(closingMatch)-1], heredocMarker) {
				// closing marker found at the start of this line; the
				// body runs up to the start of the marker line, and the
				// rest of the line is structural again
				lineStart := lineStartOf(input, i)
				appendRaw(input[bodyStart:lineStart])
				inHeredoc = false
				heredocMarker = nil
				closingMatch = nil
				i = lineStart
				continue
			}
			i += size
			continue
		}

		// detect the start of a heredoc: "<<", unquoted, unescaped,
		// starting a token
		if ch == '<' && quotes == "" && !escaped {
			if r2, s2 := utf8.DecodeRune(input[i+size:]); r2 == '<' && heredocPrecededByWhitespace(structural.Bytes()) {
				heredocMarker = heredocMarker[:0]
				heredocOpenLine = append(heredocOpenLine[:0], input[i:i+size+s2]...)
				pendingOpen = true
				i += size + s2
				continue
			}
		}

		// quote tracking, byte-oriented semantics for the ASCII quotes
		if ch == '`' {
			switch quotes {
			case "\"`":
				quotes = "\""
			case "`":
				quotes = ""
			case "\"":
				quotes = "\"`"
			default:
				quotes = "`"
			}
		} else if ch == '"' {
			switch quotes {
			case "\"":
				quotes = ""
			case "`\"":
				quotes = "`"
			case "\"`":
				quotes = ""
			case "":
				if structuralEndsWithTokenStart(structural.Bytes()) {
					quotes = "\""
				}
			}
		}

		if escaped {
			escaped = false
		} else if quotes == "" && ch == '\\' {
			escaped = true
		}

		// fold CR line endings outside of quotes and heredocs; inside
		// quoted strings bytes are kept verbatim
		if quotes == "" {
			if ch == '\r' {
				structural.WriteByte('\n')
				i += size
				// swallow the LF of a CRLF pair
				if r2, s2 := utf8.DecodeRune(input[i:]); r2 == '\n' {
					i += s2
				}
				continue
			}
		}

		structural.Write(input[i : i+size])
		i += size
	}

	if pendingOpen {
		// input ended while reading the <<MARKER opening line
		if len(heredocMarker) > 0 && heredocMarkerRegexp.MatchString(string(heredocMarker)) {
			return nil, false
		}
		structural.Write(heredocOpenLine)
	}
	if inHeredoc || quotes != "" || escaped {
		return nil, false
	}

	flushStructural()
	return segs, true
}

// lineStartOf returns the offset of the start of the line containing
// offset p (the byte after the most recent newline, or 0).
func lineStartOf(input []byte, p int) int {
	for p > 0 {
		p--
		if input[p] == '\n' {
			return p + 1
		}
	}
	return 0
}

// heredocPrecededByWhitespace reports whether the buffered structural
// text can be followed by the "<<" start of a token, i.e. the token
// position is at the beginning of the input or after whitespace.
func heredocPrecededByWhitespace(b []byte) bool {
	if len(b) == 0 {
		return true
	}
	r, _ := utf8.DecodeLastRune(b)
	return isSpace(r)
}

// structuralEndsWithTokenStart reports whether a '"' at the end of the
// buffered structural text begins a new token (the formatter only opens
// double quotes when the current position is whitespace-adjacent).
func structuralEndsWithTokenStart(b []byte) bool {
	if len(b) == 0 {
		return true
	}
	r, _ := utf8.DecodeLastRune(b)
	return isSpace(r)
}

func appendRuneBytes(buf []byte, b []byte) []byte {
	return append(buf, b...)
}

// isSpace mirrors unicode.IsSpace for the runes that are significant
// to line and token boundaries here.
func isSpace(r rune) bool {
	return r == ' ' || r == '\t' || r == '\n' || r == '\r' ||
		r == '\v' || r == '\f' || r == 0x85 || r == 0xA0 ||
		r == ' ' || r == ' ' || r == ' ' || r == ' ' ||
		r == ' ' || r == ' ' || r == ' ' || r == ' ' ||
		r == ' ' || r == ' ' || r == ' ' || r == ' ' ||
		r == ' ' || r == ' ' || r == ' ' || r == ' ' ||
		r == '　'
}

// formatSegments runs the whitespace-and-brace formatter over the
// structural segments and interleaves the raw segments unchanged.
// It returns ok=false if the structural braces are unbalanced.
func formatSegments(segs []formatSegment) ([]byte, bool) {
	out := new(bytes.Buffer)

	type heredocState int

	const (
		heredocClosed  heredocState = 0
		heredocOpening heredocState = 1
	)

	var (
		last rune // the last character that was written to the result

		space           = true // whether current/previous character was whitespace (beginning of input counts as space)
		beginningOfLine = true // whether we are at beginning of line

		openBrace        bool // whether current word/token is or started with open curly brace
		openBraceWritten bool // if openBrace, whether that brace was written or not
		openBraceSpace   bool // whether there was a non-newline space before open brace

		newLines int // count of newlines consumed

		comment bool   // whether we're in a comment
		quotes  string // encountered quotes ('', '`', '"', '"`', '`"')
		escaped bool   // whether current char is escaped

		heredoc        heredocState // whether we're reading a heredoc opening marker
		heredocEscaped bool         // whether a heredoc was escaped
		heredocMarker  []rune

		nesting int // indentation level
		braces  int // count of structural open braces minus close braces

		currentToken                  strings.Builder
		currentLineFirstToken         string
		previousLineWasTopLevelImport bool
		openBraceOwnLine              bool
	)

	finishToken := func() {
		if currentToken.Len() == 0 {
			return
		}
		if currentLineFirstToken == "" {
			currentLineFirstToken = currentToken.String()
		}
		currentToken.Reset()
	}

	finishLine := func() {
		finishToken()
		if currentLineFirstToken != "" {
			previousLineWasTopLevelImport = nesting == 0 && currentLineFirstToken == "import"
		} else if !openBrace || !openBraceOwnLine || openBraceWritten {
			previousLineWasTopLevelImport = false
		}
		currentLineFirstToken = ""
	}

	write := func(ch rune) {
		out.WriteRune(ch)
		last = ch
	}

	indent := func() {
		for tabs := nesting; tabs > 0; tabs-- {
			write('\t')
		}
	}

	nextLine := func() {
		write('\n')
		beginningOfLine = true
	}

	// emitRaw copies a raw segment to the result. After a raw heredoc
	// body the stream resumes at the line of the closing marker, which
	// the formatter indents like an ordinary structural line.
	emitRaw := func(seg formatSegment) {
		out.Write(seg.bytes)
		// recover "last" and line state from the final raw byte
		if len(seg.bytes) > 0 {
			if seg.bytes[len(seg.bytes)-1] == '\n' {
				last = '\n'
				beginningOfLine = true
				space = true
			} else {
				r, _ := utf8.DecodeLastRune(seg.bytes)
				last = r
				beginningOfLine = false
				space = false
			}
		}
	}

	for si := range segs {
		seg := &segs[si]
		if seg.raw {
			emitRaw(*seg)
			continue
		}

		rdr := strings.NewReader(seg.text)
		for {
			ch, _, err := rdr.ReadRune()
			if err != nil {
				break
			}
			// detect whether we have the start of a heredoc
			if quotes == "" && (heredoc == heredocClosed && !heredocEscaped) &&
				space && last == '<' && ch == '<' {
				write(ch)
				heredoc = heredocOpening
				space = false
				continue
			}

			if heredoc == heredocOpening {
				if ch == '\n' {
					if len(heredocMarker) > 0 && heredocMarkerRegexp.MatchString(string(heredocMarker)) {
						// the body and closing line are delivered by the
						// following raw/structural segments; simply reset
						// the opening state here
						heredocMarker = nil
						heredoc = heredocClosed
					} else {
						heredocMarker = nil
						heredoc = heredocClosed
						nextLine()
						continue
					}
					write(ch)
					continue
				}
				if isSpace(ch) {
					// a space means it's just a regular token and not a heredoc
					heredocMarker = nil
					heredoc = heredocClosed
				} else {
					heredocMarker = append(heredocMarker, ch)
					write(ch)
					continue
				}
			}

			if last == '<' && space {
				space = false
			}

			if comment {
				if ch == '\n' {
					comment = false
					space = true
					nextLine()
					continue
				}
				write(ch)
				continue
			}

			if !escaped && ch == '\\' {
				if space {
					write(' ')
					space = false
				}
				write(ch)
				escaped = true
				continue
			}

			if escaped {
				if ch == '<' {
					heredocEscaped = true
				}
				write(ch)
				escaped = false
				continue
			}

			if ch == '`' {
				switch quotes {
				case "\"`":
					quotes = "\""
				case "`":
					quotes = ""
				case "\"":
					quotes = "\"`"
				default:
					quotes = "`"
				}
			}

			if quotes == "\"" {
				if ch == '"' {
					quotes = ""
				}
				write(ch)
				continue
			}

			if ch == '"' {
				switch quotes {
				case "":
					if space {
						quotes = "\""
					}
				case "`\"":
					quotes = "`"
				case "\"`":
					quotes = ""
				}
			}

			if strings.ContainsRune(quotes, '`') {
				if ch == '`' && space && !beginningOfLine {
					write(' ')
				}
				write(ch)
				space = false
				continue
			}

			if isSpace(ch) {
				finishToken()
				space = true
				heredocEscaped = false
				if ch == '\n' {
					finishLine()
					newLines++
				}
				continue
			}
			spacePrior := space
			space = false

			//////////////////////////////////////////////////////////
			// I find it helpful to think of the formatting loop in two
			// main sections; by the time we reach this point, we
			// know we are in a "regular" part of the file: we know
			// the character is not a space, not in a literal segment
			// like a comment or quoted, it's not escaped, etc.
			//////////////////////////////////////////////////////////

			if ch == '#' {
				comment = true
			}

			if openBrace && spacePrior && !openBraceWritten {
				if nesting == 0 && last == '}' {
					nextLine()
					nextLine()
				}

				openBrace = false
				if openBraceOwnLine && previousLineWasTopLevelImport {
					if last != '\n' {
						nextLine()
					}
					indent()
				} else if beginningOfLine {
					indent()
				} else if !openBraceSpace || !isSpace(last) {
					write(' ')
				}
				write('{')
				openBraceWritten = true
				openBraceOwnLine = false
				nextLine()
				newLines = 0
				// prevent infinite nesting from ridiculous inputs (issue #4169)
				if nesting < 10 {
					nesting++
				}
				braces++
			}

			switch {
			case ch == '{':
				finishToken()
				openBrace = true
				openBraceSpace = spacePrior && !beginningOfLine
				openBraceOwnLine = newLines > 0
				if openBraceSpace && newLines == 0 {
					write(' ')
				}
				openBraceWritten = false
				if quotes == "`" {
					write('{')
					openBraceWritten = true
					openBraceOwnLine = false
					continue
				}
				continue

			case ch == '}' && (spacePrior || !openBrace):
				finishToken()
				if quotes == "`" {
					write('}')
					continue
				}
				if last != '\n' {
					nextLine()
				}
				if nesting > 0 {
					nesting--
				}
				braces--
				indent()
				write('}')
				newLines = 0
				continue
			}

			if newLines > 2 {
				newLines = 2
			}
			for i := 0; i < newLines; i++ {
				nextLine()
			}
			newLines = 0
			if beginningOfLine {
				indent()
			}
			if nesting == 0 && last == '}' && beginningOfLine {
				nextLine()
				nextLine()
			}

			if !beginningOfLine && spacePrior {
				write(' ')
			}

			if openBrace && !openBraceWritten {
				write('{')
				openBraceWritten = true
			}

			if spacePrior && ch == '<' {
				space = true
			}

			currentToken.WriteRune(ch)
			write(ch)

			beginningOfLine = false
		}
	}

	// every structural opening brace must have been closed
	if braces != 0 || openBrace && !openBraceWritten {
		return nil, false
	}

	// the Caddyfile does not need any leading or trailing spaces, but...
	trimmedResult := bytes.TrimSpace(out.Bytes())

	// ...Caddyfiles should, however, end with a newline because
	// newlines are significant to the syntax of the file
	return append(trimmedResult, '\n'), true
}

