			ch = '\n'
			if next < len(content) && content[next] == '\n' {
				next++ // swallow the LF of a CRLF pair
			}
		}

		// detect whether we have the start of a heredoc
		if quotes == "" && (heredoc == heredocClosed && !heredocEscaped) &&
			space && last == '<' && ch == '<' {
			write(ch)
			heredoc = heredocOpening
			space = false
			i = next
			continue
		}

		if heredoc == heredocOpening {
			if ch == '\n' {
				if len(heredocMarker) > 0 && heredocMarkerRegexp.MatchString(string(heredocMarker)) {
					// The opening marker line is structural, so its
					// line ending is the normalized LF already written.
					write('\n')

					// Everything from here through the closing marker
					// line is copied from the input byte-for-byte.
					bodyStart := next
					closeEnd, ok := findHeredocClose(content, bodyStart, string(heredocMarker))
