					// and closing marker line had just been read.
					heredocMarker = nil
					heredoc = heredocClosed
					finishLine()
					space = true
					beginningOfLine = true
					last = '\n'
					newLines = 0
					i = closeEnd
					continue
				}
				heredocMarker = nil
				heredoc = heredocClosed
				nextLine()
				i = next
				continue
			}
			if unicode.IsSpace(ch) {
				// a space means it's just a regular token and not a heredoc
				heredocMarker = nil
				heredoc = heredocClosed
			} else {
				heredocMarker = append(heredocMarker, ch)
				write(ch)
				i = next
				continue
			}
		}

