				nextLine()
			}

			openBrace = false
			if openBraceOwnLine && previousLineWasTopLevelImport {
				if last != '\n' {
					nextLine()
				}
				indent()
			} else if beginningOfLine {
				indent()
			} else if !openBraceSpace || !unicode.IsSpace(last) {
