	if invalid || quotes != "" || escaped || braces != 0 || (openBrace && !openBraceWritten) {
		return copyBytes(input)
	}

	// the Caddyfile does not need any leading or trailing spaces, but...
	trimmedResult := bytes.TrimSpace(out.Bytes())

	// ...Caddyfiles should, however, end with a newline because
	// newlines are significant to the syntax of the file.
	// Build a fresh slice so the result never aliases the input.
	result := make([]byte, 0, len(utf8BOM)+len(trimmedResult)+1)
	if hasBOM {
		result = append(result, utf8BOM...)
	}
	result = append(result, trimmedResult...)
	result = append(result, '\n')
	return result
}

// findHeredocClose locates the heredoc closing marker within content,
// starting at bodyStart (the byte immediately after the opening
// marker's newline). The closing marker takes effect only on an
// original line boundary: a line consisting solely of horizontal
// whitespace, the marker, and a line ending (LF, CRLF, or bare CR).
// It returns the offset immediately following the closing line's
// line ending, or ok=false if the heredoc is unterminated.
func findHeredocClose(content []byte, bodyStart int, marker string) (int, bool) {
	p := bodyStart
	for p < len(content) {
		lineStart := p

		lineEnd := p
		for lineEnd < len(content) && content[lineEnd] != '\n' && content[lineEnd] != '\r' {
			lineEnd++
		}

		if lineEnd == len(content) {
			// the last line has no line ending, so a marker on it
			// is not on an original line boundary
			return 0, false
		}

		line := bytes.TrimLeft(content[lineStart:lineEnd], " \t")
		line = bytes.TrimRight(line, " \t")
		if string(line) == marker {
			end := lineEnd + 1
			if content[lineEnd] == '\r' && end < len(content) && content[end] == '\n' {
				end++
			}
			return end, true
		}

		// advance past the line ending
		p = lineEnd + 1
		if content[lineEnd] == '\r' && p < len(content) && content[p] == '\n' {
			p++
		}
	}
	return 0, false
}

// truncatedBOMPrefixLen reports whether input starts with a proper,
// non-empty prefix of the UTF-8 BOM without being the complete BOM.
func truncatedBOMPrefixLen(input []byte) int {
	n := len(input)
	if n == 0 || n >= len(utf8BOM) || input[0] != utf8BOM[0] {
		return 0
	}
	for i := 0; i < n; i++ {
		if input[i] != utf8BOM[i] {
			return 0
		}
	}
	return n
}

// copyBytes returns a slice that does not alias b.
func copyBytes(b []byte) []byte {
	if len(b) == 0 {
		return nil
	}
	out := make([]byte, len(b))
	copy(out, b)
	return out
}

