		}
		currentLineFirstToken = ""
	}

	write := func(ch rune) {
		out.WriteRune(ch)
		last = ch
	}

	indent := func() {
		for tabs := nesting; tabs > 0; tabs-- {
			write('\t')
		}
	}

	nextLine := func() {
		write('\n')
		beginningOfLine = true
	}

	for i := 0; i < len(content); {
		ch, size := utf8.DecodeRune(content[i:])
		next := i + size

		// Normalize CR and CRLF line endings on structural lines.
		// Quoted arguments, escaped characters, and heredoc bodies
		// never reach this fold.
		if ch == '\r' && quotes == "" && !escaped {
			ch = '\n'
			if next < len(content) && content[next] == '\n' {
				next++ // swallow the LF of a CRLF pair
			}
		}

		// detect whether we have the start of a heredoc
		if quotes == "" && (heredoc == heredocClosed && !heredocEscaped) &&
			space && last == '<' && ch == '<' {
			write(ch)
			heredoc = heredocOpening
			space = false
			i = next
			continue
		}

		if heredoc == heredocOpening {
			if ch == '\n' {
				if len(heredocMarker) > 0 && heredocMarkerRegexp.MatchString(string(heredocMarker)) {
					// The opening marker line is structural, so its
					// line ending is the normalized LF already written.
					write('\n')

					// Everything from here through the closing marker
					// line is copied from the input byte-for-byte.
					bodyStart := next
					closeEnd, ok := findHeredocClose(content, bodyStart, string(heredocMarker))
					if !ok {
						invalid = true
						break
					}
					out.Write(content[bodyStart:closeEnd])

					// Resume structural formatting as though the body
					// and closing marker line had just been read.
					heredocMarker = nil
					heredoc = heredocClosed
					finishLine()
					space = true
					beginningOfLine = true
					last = '\n'
					newLines = 0
					i = closeEnd
					continue
				}
				heredocMarker = nil
				heredoc = heredocClosed
				nextLine()
				i = next
				continue
			}
			if unicode.IsSpace(ch) {
				// a space means it's just a regular token and not a heredoc
				heredocMarker = nil
				heredoc = heredocClosed
			} else {
				heredocMarker = append(heredocMarker, ch)
				write(ch)
				i = next
				continue
			}
		}

		if last == '<' && space {
			space = false
		}

		if comment {
			if ch == '\n' {
				comment = false
				space = true
				nextLine()
				i = next
				continue
			}
			write(ch)
			i = next
			continue
		}

		if !escaped && ch == '\\' {
			if space {
				write(' ')
				space = false
			}
			write(ch)
			escaped = true
			i = next
			continue
		}

		if escaped {
			if ch == '<' {
				heredocEscaped = true
			}
			write(ch)
			escaped = false
			i = next
			continue
		}

		if ch == '`' {
			switch quotes {
			case "\"`":
				quotes = "\""
			case "`":
				quotes = ""
			case "\"":
				quotes = "\"`"
			default:
				quotes = "`"
			}
		}

		if quotes == "\"" {
			if ch == '"' {
				quotes = ""
			}
			write(ch)
			i = next
			continue
		}

		if ch == '"' {
			switch quotes {
			case "":
				if space {
					quotes = "\""
				}
			case "`\"":
				quotes = "`"
			case "\"`":
				quotes = ""
			}
		}

		if strings.Contains(quotes, "`") {
			if ch == '`' && space && !beginningOfLine {
				write(' ')
			}
			write(ch)
			space = false
			i = next
			continue
		}

		if unicode.IsSpace(ch) {
			finishToken()
			space = true
			heredocEscaped = false
			if ch == '\n' {
				finishLine()
				newLines++
			}
			i = next
			continue
		}
		spacePrior := space
		space = false

		//////////////////////////////////////////////////////////
		// I find it helpful to think of the formatting loop in two
		// main sections; by the time we reach this point, we
		// know we are in a "regular" part of the file: we know
		// the character is not a space, not in a literal segment
		// like a comment or quoted, it's not escaped, etc.
		//////////////////////////////////////////////////////////

		if ch == '#' {
			comment = true
		}

		if openBrace && spacePrior && !openBraceWritten {
			if nesting == 0 && last == '}' {
				nextLine()
				nextLine()
			}

			openBrace = false
			if openBraceOwnLine && previousLineWasTopLevelImport {
				if last != '\n' {
					nextLine()
				}
				indent()
			} else if beginningOfLine {
				indent()
			} else if !openBraceSpace || !unicode.IsSpace(last) {
				write(' ')
			}
			write('{')
			openBraceWritten = true
			openBraceOwnLine = false
			nextLine()
			newLines = 0
			// prevent infinite nesting from ridiculous inputs (issue #4169)
			if nesting < 10 {
				nesting++
			}
			braces++
		}

		switch {
		case ch == '{':
			finishToken()
			openBrace = true
			openBraceSpace = spacePrior && !beginningOfLine
			openBraceOwnLine = newLines > 0
			if openBraceSpace && newLines == 0 {
				write(' ')
			}
			openBraceWritten = false
			if quotes == "`" {
				write('{')
				openBraceWritten = true
				openBraceOwnLine = false
				i = next
				continue
			}

		case ch == '}' && (spacePrior || !openBrace):
			finishToken()
			if quotes == "`" {
				write('}')
				i = next
				continue
			}
			if last != '\n' {
				nextLine()
			}
			if nesting > 0 {
				nesting--
			}
			braces--
			indent()
			write('}')
			newLines = 0
			i = next
			continue
		}

		if newLines > 2 {
			newLines = 2
		}
		for n := 0; n < newLines; n++ {
			nextLine()
		}
		newLines = 0
		if beginningOfLine {
			indent()
		}
		if nesting == 0 && last == '}' && beginningOfLine {
			nextLine()
			nextLine()
		}

		if !beginningOfLine && spacePrior {
			write(' ')
		}

		if openBrace && !openBraceWritten {
			write('{')
			openBraceWritten = true
		}

		if spacePrior && ch == '<' {
			space = true
		}

		currentToken.WriteRune(ch)
		write(ch)

		beginningOfLine = false
		i = next
	}

	// a valid opening marker that never reached its opening newline
	// is an unterminated heredoc
	if heredoc == heredocOpening && len(heredocMarker) > 0 &&
		heredocMarkerRegexp.MatchString(string(heredocMarker)) {
		invalid = true
	}

	// malformed inputs are returned unchanged, byte-for-byte
	if invalid || quotes != "" || escaped || braces != 0 || (openBrace && !openBraceWritten) {
		return copyBytes(input)
	}

	// the Caddyfile does not need any leading or trailing spaces, but...
	trimmedResult := bytes.TrimSpace(out.Bytes())

	// ...Caddyfiles should, however, end with a newline because
	// newlines are significant to the syntax of the file.
	// Build a fresh slice so the result never aliases the input.
	result := make([]byte, 0, len(utf8BOM)+len(trimmedResult)+1)
	if hasBOM {
		result = append(result, utf8BOM...)
	}
	result = append(result, trimmedResult...)
	result = append(result, '\n')
	return result
}

// findHeredocClose locates the heredoc closing marker within content,
// starting at bodyStart (the byte immediately after the opening
// marker's newline). The closing marker takes effect only on an
// original line boundary: a line consisting solely of horizontal
// whitespace, the marker, and a line ending (LF, CRLF, or bare CR).
// It returns the offset immediately following the closing line's
// line ending, or ok=false if the heredoc is unterminated.
func findHeredocClose(content []byte, bodyStart int, marker string) (int, bool) {
	p := bodyStart
	for p < len(content) {
		lineStart := p

		lineEnd := p
		for lineEnd < len(content) && content[lineEnd] != '\n' && content[lineEnd] != '\r' {
			lineEnd++
		}

		if lineEnd == len(content) {
			// the last line has no line ending, so a marker on it
			// is not on an original line boundary
			return 0, false
		}

		line := bytes.TrimLeft(content[lineStart:lineEnd], " \t")
		line = bytes.TrimRight(line, " \t")
		if string(line) == marker {
			end := lineEnd + 1
			if content[lineEnd] == '\r' && end < len(content) && content[end] == '\n' {
				end++
			}
			return end, true
		}

		// advance past the line ending
		p = lineEnd + 1
		if content[lineEnd] == '\r' && p < len(content) && content[p] == '\n' {
			p++
		}
	}
	return 0, false
}

// truncatedBOMPrefixLen reports whether input starts with a proper,
// non-empty prefix of the UTF-8 BOM without being the complete BOM.
func truncatedBOMPrefixLen(input []byte) int {
	n := len(input)
	if n == 0 || n >= len(utf8BOM) || input[0] != utf8BOM[0] {
		return 0
	}
	for i := 0; i < n; i++ {
		if input[i] != utf8BOM[i] {
			return 0
		}
	}
	return n
}

// copyBytes returns a slice that does not alias b.
func copyBytes(b []byte) []byte {
	if len(b) == 0 {
		return nil
	}
	out := make([]byte, len(b))
	copy(out, b)
	return out
}

