// findHeredocClose locates the heredoc closing marker within content,
// starting at bodyStart (the byte immediately after the opening
// marker's line ending). The closing marker takes effect only on an
// original line boundary: a line consisting solely of horizontal
// whitespace, the marker, optional trailing horizontal whitespace, and
// a line ending (LF, CRLF, or bare CR). It returns the bounds of:
//   - lineStart:  start of the closing marker line
//   - markerStart: first byte of the marker (after leading whitespace)
//   - lineEnd:    first byte of the line ending (after trailing
//     horizontal whitespace)
//   - termLen:    length of the line ending (1 or 2 bytes)
//
// ok is false if no such line exists, including when the marker only
// appears on a final line without a line ending.
func findHeredocClose(content []byte, bodyStart int, marker string) (lineStart, markerStart, lineEnd, termLen int, ok bool) {
	p := bodyStart
	for p < len(content) {
		lineStart = p

		lineEnd = p
		for lineEnd < len(content) && content[lineEnd] != '\n' && content[lineEnd] != '\r' {
			lineEnd++
		}

		if lineEnd == len(content) {
			// the last line has no line ending, so a marker on it
			// is not on an original line boundary
			return 0, 0, 0, 0, false
		}

		trimmed := bytes.TrimLeft(content[lineStart:lineEnd], " \t")
		markerStart = lineEnd - len(trimmed)
		trimmed = bytes.TrimRight(trimmed, " \t")

		if string(trimmed) == marker {
			termLen = 1
