				termLen = 2
			}
			lineEnd -= len(bytes.TrimRight(content[markerStart:lineEnd], " \t")) - len(trimmed)
			return lineStart, markerStart, lineEnd, termLen, true
		}

		// advance past the line ending
		p = lineEnd + 1
		if content[lineEnd] == '\r' && p < len(content) && content[p] == '\n' {
			p++
		}
	}
