				openBraceWritten = true
				openBraceOwnLine = false
				i = next
				continue
			}

		case ch == '}' && (spacePrior || !openBrace):
			finishToken()
			if quotes == "`" {
				write('}')
				i = next
				continue
			}
			if last != '\n' {
				nextLine()
			}
			if nesting > 0 {
				nesting--
			}
			braces--
			indent()
			write('}')
			newLines = 0
			i = next
			continue
		}

		if newLines > 2 {
			newLines = 2
		}
		for n := 0; n < newLines; n++ {
			nextLine()
		}
		newLines = 0
		if beginningOfLine {
			indent()
		}
		if nesting == 0 && last == '}' && beginningOfLine {
			nextLine()
			nextLine()
		}

		if !beginningOfLine && spacePrior {
			write(' ')
		}

