	// Locate the closing marker line on an original
	// line boundary and copy the body byte-for-byte.
	bodyStart := next
	lineStart, markerStart, contentEnd, lineEnd, _, found :=
		findHeredocClose(content, bodyStart, string(heredocMarker))
	if !found {
		invalid = true
		break
	}

	// raw heredoc body, including any spaces, tabs,
	// carriage returns, braces, and comment bytes
	out.Write(content[bodyStart:lineStart])

	// The closing marker line is structural, but its
	// leading whitespace determines the heredoc
	// padding shared with the body lines, so it is
	// copied verbatim; trailing whitespace and the line
	// ending follow the usual formatting rules.
	out.Write(content[lineStart:markerStart])
	out.Write(content[markerStart:contentEnd])

	heredocMarker = nil
	heredoc = heredocClosed
	finishLine()
	space = true
	beginningOfLine = true
	last = '\n'
	newLines = 0

	// resume at the closing line terminator so the
	// newline is counted and folded normally
	i = lineEnd
	continue
}
