// padding and is copied as heredoc body bytes. It returns the bounds of:
//   - lineStart:   start of the closing marker line
//   - markerStart: first byte of the marker (after leading padding)
//   - contentEnd:  byte immediately after the marker (before trailing
//     horizontal whitespace)
//   - lineEnd:     first byte of the line ending
//   - termLen:     length of the line ending (1 or 2 bytes)
//
// ok is false if no such line exists, including when the marker only
// appears on a final line without a line ending.
func findHeredocClose(content []byte, bodyStart int, marker string) (lineStart, markerStart, contentEnd, lineEnd, termLen int, ok bool) {
	p := bodyStart
	for p < len(content) {
		lineStart = p

		lineEnd = p
		for lineEnd < len(content) && content[lineEnd] != '\n' && content[lineEnd] != '\r' {
			lineEnd++
		}

		if lineEnd == len(content) {
			// the last line has no line ending, so a marker on it
			// is not on an original line boundary
			return 0, 0, 0, 0, 0, false
		}

		trimmedEnd := lineEnd - len(bytes.TrimRight(content[p:lineEnd], " \t"))
		if trimmedEnd-len(marker) >= lineStart &&
			string(content[trimmedEnd-len(marker):trimmedEnd]) == marker {
			markerStart = trimmedEnd - len(marker)
			contentEnd = trimmedEnd
			termLen = 1
			if content[lineEnd] == '\r' && lineEnd+1 < len(content) && content[lineEnd+1] == '\n' {
				termLen = 2
			}
			return lineStart, markerStart, contentEnd, lineEnd, termLen, true
		}

		// advance past the line ending
		p = lineEnd + 1
		if content[lineEnd] == '\r' && p < len(content) && content[p] == '\n' {
			p++
		}
	}
	return 0, 0, 0, 0, 0, false
}

