// findHeredocClose scans a heredoc body starting at bodyStart and
// locates the closing marker. The marker takes effect only on an
// original line boundary: it must immediately precede a whitespace
// rune (a line ending, or any other whitespace that ends the marker
// line). Everything before the marker — including its indentation
// padding — is part of the raw body. It returns the bounds of:
//   - markerStart: offset of the marker's first rune
//   - markerEnd:   offset of the whitespace rune that closes the heredoc
//   - wsPos:       same as markerEnd; scanning resumes there so the
//     whitespace is handled structurally
//
// ok is false when the heredoc is not closed before end of input; a
// marker on a final line without any trailing whitespace does not
// close it.
func findHeredocClose(content []byte, bodyStart int, marker []rune) (markerStart, markerEnd, wsPos int, ok bool) {
	// the last len(marker)+1 (rune, offset) pairs
	type runePos struct {
		r rune
		p int
	}
	var window []runePos

	for i := bodyStart; i < len(content); {
		r, size := utf8.DecodeRune(content[i:])
		window = append(window, runePos{r, i})
		if len(window) > len(marker)+1 {
			window = window[1:]
		}

		if unicode.IsSpace(r) && len(window) >= len(marker)+1 {
			match := true
			for k := 0; k < len(marker); k++ {
				if window[len(window)-2-k].r != marker[len(marker)-1-k] {
					match = false
					break
				}
			}
			if match {
				return window[len(window)-1-len(marker)].p, i, i, true
			}
		}

		// a newline starts a fresh marker candidate line
		if r == '\n' {
			window = window[:0]
		}

		i += size
	}
	return 0, 0, 0, false
}

