package caddyfile

import (
	"bytes"
	"fmt"
	"testing"
)

func dbgFmt(in string) string { return string(Format([]byte(in))) }

func TestDbgSpec(t *testing.T) {
	bom := "\xef\xbb\xbf"
	cases := []string{
		// BOM
		bom + "a {\n\tb\n}\n",
		bom + "a {\n\tb\n}\r\n",
		"x \xef\xbb\xbf y\n",                 // BOM mid-content
		"respond \"\xef\xbb\xbf\"\n",         // BOM in quoted arg
		"h <<E\nbody \xef\xbb\xbf here\nE\n", // BOM in heredoc
		"\xef", "\xef\xbb",                    // truncated BOM
		bom + bom + "a\n",                     // double BOM (only one file marker)
		// line endings
		"a {\r\n\tb\r\n}\r\n",
		"a {\r\tb\r}\r",
		"a {\n\tb\r\n\tc\n}\n",
		"# c\r\nb\r\n",
		"respond \"a\rb\"\n",
		// heredoc bodies raw
		"h <<E\n  sp  sp\ttab\rCR { } # x\nE\n",
		"h <<E\nbody\n  E  \n}\n",     // padded marker + trailing
		"h <<E\nbody\nE",              // marker at EOF, no terminator
		"h <<E\nbody\nEX\nE\n",        // EX is not marker
		// malformed
		"a {\n b\n",          // unclosed brace
		"a {\n b\n}\n}\n",    // extra close
		"respond \"oops\n",   // unclosed quote
		"foo \\\n",           // dangling escape
		"h <<E\nbody\n",      // unterminated heredoc
		// normal idempotency
		"a {\n\tb\n}\n",
		"import ./x.caddy\nimport ./y.caddy\n",
		"respond \"\" \"x\"\n",
		"a{}{}\n",
	}
	for _, c := range cases {
		fmt.Printf("IN  %q\nOUT %q\n\n", c, dbgFmt(c))
	}

	// idempotency
	for _, c := range cases {
		first := Format([]byte(c))
		second := Format(first)
		if !bytes.Equal(first, second) {
			t.Errorf("NOT IDEMPOTENT: %q\n -> %q\n -> %q", c, first, second)
		}
	}
}
EOF
