package caddyfile

import (
	"bytes"
	"testing"
	"unicode/utf8"
)

// realistic Caddyfile byte alphabet
var alpha = []byte("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 \t\r\n{}#\"`\\<>_/-.:*?{}$EFMBOM,")

func FuzzFormatRealistic(f *testing.F) {
	f.Add([]byte("a {\n\tb <<E\nx y\nE\n}\n"))
	f.Add([]byte("\xef\xbb\xbfx {\r\n b\r\n}\r\n"))
	f.Fuzz(func(t *testing.T, n int) {
		if n < 0 { n = -n }
		l := n % 40
		b := make([]byte, 0, l+3)
		for k := 0; k < l; k++ {
			b = append(b, alpha[(n+k*7)%len(alpha)])
		}
		// occasionally prefix a BOM or truncated BOM
		switch n % 7 {
		case 0:
			b = append([]byte{0xEF, 0xBB, 0xBF}, b...)
		case 1:
			b = append([]byte{0xEF}, b...)
		}
		out := Format(b)
		if !utf8.Valid(b) || !utf8.Valid(out) {
			return
		}
		// determinism
		if !bytes.Equal(out, Format(append([]byte(nil), b...))) {
			t.Fatal("non-deterministic")
		}
		// idempotency for well-formed outputs
		if !bytes.Equal(out, Format(out)) {
			t.Fatalf("not idempotent\nin : %q\nout: %q\n2nd: %q", b, out, Format(out))
		}
	})
}

func FuzzFormatRawNoPanic(f *testing.F) {
	f.Add([]byte{0xEF, 0xBB})
	f.Fuzz(func(t *testing.T, b []byte) {
		out := Format(b)
		_ = Format(out)
	})
}
EOF
