			b = append(b, []byte(fmt.Sprintf("respond   %q   %d", "hi", 200+r.Intn(5)))...)
			if r.Intn(3)==0 { b = append(b, '\r') }
			b = append(b, '\n')
			if r.Intn(4)==0 { b = append(b, '\n') }
		}
		b = append(b, '}')
		b = append(b, '\n')
		if k+1 < blocks { b = append(b, '\n') }
	}
	return b
}

func TestDbgValidNormalized(t *testing.T) {
	r := rand.New(rand.NewSource(42))
	passthrough, reformatted := 0, 0
	for k := 0; k < 20000; k++ {
		in := genValid(r)
		out := Format(append([]byte(nil), in...))
		if !bytes.Equal(out, Format(out)) { t.Fatalf("not idempotent: %q", in) }
		// every messy valid file must actually be normalized (CRLF gone,
		// trailing spaces gone), never silently passed through
		if bytes.Equal(out, in) {
			// acceptable only if input already canonical
			if bytes.Contains(in, []byte("\r")) || bytes.Contains(in, []byte("   ")) {
				t.Fatalf("messy valid file passed through unformatted:\n%q", in)
			}
			passthrough++
		} else {
			reformatted++
		}
	}
	t.Logf("valid files: %d reformatted, %d already canonical (all idempotent)", reformatted, passthrough)
}
EOF
go test ./caddyconfig/caddyfile/ -run TestDbgValidNormalized -v -count=1 2>&1 | grep -E "valid files|FAIL|PASS"; rm caddyconfig/caddyfile/dbg_test.go
